// Maps between story progress (0..1), narration tracks and caption lines.
// Ranges come from src/data/narration.js (generated by scripts/sync-captions.py).
import { tracks } from '../data/narration';

/** which track + line owns story progress p */
export function locate(p) {
  let ti = tracks.findIndex((t) => p < t.scroll[1]);
  if (ti < 0) ti = tracks.length - 1;
  const lines = tracks[ti].lines;
  let li = lines.findIndex((l) => p < l.scroll[1]);
  if (li < 0) li = lines.length - 1;
  return { ti, li };
}

/** story progress for a moment in a track (time → scroll is linear inside each act) */
export function progressAt(ti, time) {
  const t = tracks[ti];
  const f = Math.min(1, Math.max(0, time / t.duration));
  return t.scroll[0] + (t.scroll[1] - t.scroll[0]) * f;
}

/** which line is being spoken at `time` in track ti */
export function lineAtTime(ti, time) {
  const lines = tracks[ti].lines;
  for (let i = lines.length - 1; i >= 0; i--) if (time >= lines[i].start - 0.05) return i;
  return 0;
}

/** when self-pilot should stop playing line li (just before the next sentence) */
export function lineStopTime(ti, li) {
  const t = tracks[ti];
  const next = t.lines[li + 1];
  return next ? Math.min(t.lines[li].end + 0.3, next.start - 0.02) : t.duration + 1;
}

export const ACT_STARTS = tracks.map((t) => t.scroll[0]);
